values ('00000000-0000-4000-8000-000000005001', '00000000-0000-4000-8000-000000001001', 'published', 1, '[{"id":"explore","type":"multiple_choice_explore","phase":"activity","prompt":"Tap each one. Which of these uses AI to decide what to do?","options":[{"id":"calc","text":"A calculator adding 24 + 18","feedback":"No AI here — a calculator follows exact rules someone wrote. Same input, same answer, every time."},{"id":"feed","text":"A video app choosing what to show you next","feedback":"Yes! It learned from millions of viewers what people like you tend to watch next."},{"id":"fan","text":"A fan that turns on with a switch","feedback":"No AI — it''s a simple circuit. On or off, nothing to learn."},{"id":"photos","text":"A phone grouping photos by face","feedback":"Yes! It learned what faces look like from lots of examples."}]},{"id":"notice","type":"reflection_prompt","phase":"reflection","prompt":"What did the AI examples have in common that the others didn''t?","placeholder":"I noticed that…","min_chars":20},{"id":"concept","type":"rich_text","phase":"module","markdown":"## Rules vs. learning\n\nA **normal program** follows rules a person wrote: *if this, then that*.\n\nAn **AI system** works out its own rules by looking at **lots of examples** — like thousands of photos labelled \"cat\" or \"not cat\". That''s why AI can handle messy things like faces, voices and handwriting."},{"id":"picture","type":"image","phase":"module","src":"/seed/rules-vs-learning.svg","alt":"Left: a person writing rules for a computer. Right: a computer looking at many labelled examples.","caption":"Rules are written by people. Patterns are learned from examples."},{"id":"fun","type":"callout","phase":"module","variant":"fun_fact","title":"Did you know?","markdown":"Your phone keyboard''s next-word suggestions come from a small AI model that learned from lots of text."},{"id":"check","type":"quiz","phase":"check","title":"Quick check","passing_score":60,"questions":[{"kind":"mcq","id":"q1","prompt":"What makes an AI system different from a normal program?","options":[{"id":"a","text":"It is always faster"},{"id":"b","text":"It learns patterns from examples"},{"id":"c","text":"It never makes mistakes"}],"correct_option_id":"b","explanation":"AI learns patterns from examples instead of only following hand-written rules — and it can still make mistakes!"},{"kind":"true_false","id":"q2","statement":"A calculator uses AI to add numbers.","answer":false,"explanation":"A calculator follows exact rules. No learning needed."}]}]'::jsonb, now())
on conflict (id) do nothing;

