insert into public.lesson_versions (id, lesson_id, status, version, blocks, published_at)
values ('00000000-0000-4000-8000-000000005002', '00000000-0000-4000-8000-000000001002', 'published', 1, '[{"id":"order","type":"drag_sort","phase":"activity","prompt":"You want to teach a computer to recognise mangoes. Put these steps in order.","items":[{"id":"collect","text":"Collect lots of fruit photos"},{"id":"label","text":"Label each photo: mango or not mango"},{"id":"train","text":"Let the computer look for patterns"},{"id":"test","text":"Test it on photos it has never seen"}],"feedback_correct":"Exactly how real AI training works!","feedback_incorrect":"Close! Think: what do you need before the computer can look for patterns?"},{"id":"notice","type":"reflection_prompt","phase":"reflection","prompt":"What did you notice? Write one or two sentences.","placeholder":"I noticed that…","min_chars":20},{"id":"video","type":"video","phase":"module","title":"How a neural network learns (sample video — replace with your own)","provider":"youtube","url":"https://www.youtube-nocookie.com/embed/aircAruvnKk","transcript":"Sample video. Replace with a Class 7–8 friendly explainer and add a captions file."},{"id":"concept","type":"rich_text","phase":"module","markdown":"## Training data\n\nThe examples an AI learns from are called **training data**. Good training data is:\n\n- **Big** — many examples\n- **Varied** — ripe, raw, cut, in a basket…\n- **Correctly labelled** — wrong labels teach wrong patterns"},{"id":"points","type":"key_points","phase":"module","title":"Remember","points":["AI learns from examples called training data","Testing uses examples it has never seen","Bad data → bad AI"]},{"id":"check","type":"quiz","phase":"check","title":"Quick check","passing_score":60,"questions":[{"kind":"short_answer","id":"q1","prompt":"What do we call the examples an AI learns from? (two words)","accepted_answers":["training data","training-data"],"explanation":"They''re called training data."},{"kind":"mcq","id":"q2","prompt":"Why do we test with new photos?","options":[{"id":"a","text":"To check it learned the pattern, not just memorised"},{"id":"b","text":"Because old photos are blurry"}],"correct_option_id":"a","explanation":"New photos show whether the AI really learned what a mango looks like."}]}]'::jsonb, now())
on conflict (id) do nothing;

