values ('00000000-0000-4000-8000-000000006001', '00000000-0000-4000-8000-000000002001', 'published', 1, '[{"id":"match","type":"match_pairs","phase":"activity","prompt":"Match each input with what an AI might learn to predict from it.","pairs":[{"id":"p1","left":"A photo of a leaf","right":"Plant disease"},{"id":"p2","left":"A voice recording","right":"The words spoken"},{"id":"p3","left":"Past weather readings","right":"Tomorrow''s rain"},{"id":"p4","left":"An email","right":"Spam or not spam"}]},{"id":"notice","type":"reflection_prompt","phase":"reflection","prompt":"What did you notice? Write one or two sentences.","placeholder":"I noticed that…","min_chars":20},{"id":"concept","type":"rich_text","phase":"module","markdown":"## Inputs and outputs\n\nEvery AI model takes an **input** (a photo, a sound, numbers) and gives an **output** (a label, a word, a number). It learns the link between them from examples."},{"id":"points","type":"key_points","phase":"module","title":"Key points","points":["Input → model → output","The model learns the link from examples"]},{"id":"check","type":"quiz","phase":"check","title":"Quick check","passing_score":60,"questions":[{"kind":"true_false","id":"q1","statement":"A spam filter''s input is an email.","answer":true,"explanation":"It reads the email and outputs spam / not spam."}]}]'::jsonb, now())
