values ('00000000-0000-4000-8000-000000006006', '00000000-0000-4000-8000-000000002006', 'published', 1, '[{"id":"task","type":"external_task","phase":"activity","tool_id":"00000000-0000-4000-8000-000000009003","goal":"Publish a one-page website about your favourite animal and share its link.","steps":[{"id":"s1","text":"Copy the starter prompt and ask your approved AI helper to write an index.html file."},{"id":"s2","text":"Save the code as index.html inside a new folder on your computer."},{"id":"s3","text":"Click Launch tool. Drag the whole folder onto the Netlify Drop page."},{"id":"s4","text":"Copy the link that ends in .netlify.app and paste it below."}],"starter_prompts":[{"id":"p1","label":"Starter prompt","text":"Write a single index.html file (HTML + CSS, no JavaScript) for a colourful one-page website about the [animal]. Include a title, 3 fun facts and a short quiz question at the bottom. Keep it suitable for a 13-year-old."}],"estimated_minutes":20,"submission_types":["url","screenshot"],"fallback":{"kind":"with_parent","instructions":"Netlify needs you to be 13 or older. Ask a parent or guardian to do the **Launch tool** step with you on their device, then paste the link here together."}},{"id":"notice","type":"reflection_prompt","phase":"reflection","prompt":"Which part did the AI do well, and what did you have to fix yourself?","placeholder":"I noticed that…","min_chars":20},{"id":"concept","type":"rich_text","phase":"module","markdown":"## AI as a helper\n\nAI tools can draft code fast, but **you** are the editor: check facts, fix mistakes and decide what''s good."},{"id":"points","type":"key_points","phase":"module","title":"Remember","points":["Check what AI writes","Never share personal details on a public page","You''re the editor"]},{"id":"check","type":"quiz","phase":"check","title":"Quick check","passing_score":60,"questions":[{"kind":"mcq","id":"q1","prompt":"What should you NEVER put on your public page?","options":[{"id":"a","text":"Fun facts about animals"},{"id":"b","text":"Your home address or phone number"}],"correct_option_id":"b","explanation":"Public pages can be seen by anyone. Keep personal details private."}]}]'::jsonb, now())
